"""Writes crates/ciplink/src/tables.rs from the reference Python lookup tables (generated, do not edit by hand)."""

import json
import os

from fixturelib import ROOT

from ciplink.cip import (SERVICE_STATUS, EXTEND_CODES, STATUS, KEYSWITCH, EXTERNAL_ACCESS, PRODUCT_TYPES, VENDORS,
                         STATES, PCCC_ERROR_CODE)


def lit(text):
    return json.dumps(text, ensure_ascii=False)


def match_fn(name, arg, typ, table, doc, vis="pub(crate)"):
    arms = "\n".join(f"        {key} => Some({lit(value)})," for key, value in sorted(table.items()))
    return (f"/// {doc}\n{vis} fn {name}({arg}: {typ}) -> Option<&'static str> {{\n    match {arg} {{\n{arms}\n"
            f"        _ => None,\n    }}\n}}\n")


def main():
    out = ["// Generated by tools/fixtures/gen_tables_rs.py from the ciplink 0.2.0 Python tables. Do not edit.\n"]
    out.append(match_fn("service_status", "status", "u8", SERVICE_STATUS,
                        "CIP general status text (1756-RM003)."))
    arms = []
    for status, codes in sorted(EXTEND_CODES.items()):
        for ext, text in sorted(codes.items()):
            arms.append(f"        ({status:#04x}, {ext:#06x}) => Some({lit(text)}),")
    out.append("/// Extended status text of a general status and its first extended status word.\n"
               "pub(crate) fn extend_code(status: u8, ext: u16) -> Option<&'static str> {\n"
               "    match (status, ext) {\n" + "\n".join(arms) + "\n        _ => None,\n    }\n}\n")
    out.append(match_fn("encap_status", "status", "u32", STATUS, "EtherNet/IP encapsulation status text."))
    arms = [f"        ({a}, {b}) => Some({lit(text)})," for a, codes in sorted(KEYSWITCH.items())
            for b, text in sorted(codes.items())]
    out.append("/// Keyswitch position from the two Identity status bytes (Rockwell KB 28917).\n"
               "pub(crate) fn keyswitch(a: u8, b: u8) -> Option<&'static str> {\n    match (a, b) {\n"
               + "\n".join(arms) + "\n        _ => None,\n    }\n}\n")
    out.append(match_fn("external_access", "access", "u8", EXTERNAL_ACCESS, "Logix symbol External Access text."))
    out.append(match_fn("state", "state", "u8", {k: v for k, v in STATES.items() if isinstance(k, int) and k < 256},
                        "Identity Object state text.", vis="pub"))
    out.append(match_fn("product_type", "code", "u16", {k: v for k, v in PRODUCT_TYPES.items() if isinstance(k, int)},
                        "CIP device (product) type name.", vis="pub"))
    out.append(match_fn("vendor", "id", "u16", {k: v for k, v in VENDORS.items() if isinstance(k, int)},
                        "CIP vendor name.", vis="pub"))
    out.append(match_fn("pccc_error", "code", "i32", PCCC_ERROR_CODE, "PCCC status text."))
    path = os.path.join(ROOT, "crates", "ciplink", "src", "tables.rs")
    with open(path, "w", encoding="utf-8", newline="\n") as file:
        file.write("\n".join(out))
    print(f"wrote {os.path.relpath(path, ROOT)}")


if __name__ == "__main__":
    main()
